# Good! McGee graph is 3-regular with 24 vertices. Let's verify girth.

def bfs_girth(edges, n):
    """Compute girth of graph"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    min_cycle = float('inf')

    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        qi = 0
        while qi < len(queue):
            node = queue[qi]; qi += 1
            for nb in adj[node]:
                if nb not in dist:
                    dist[nb] = dist[node] + 1
                    parent[nb] = node
                    queue.append(nb)
                elif parent[node] != nb:
                    # Found a cycle
                    cycle_len = dist[node] + dist[nb] + 1
                    min_cycle = min(min_cycle, cycle_len)

    return min_cycle

