from collections import defaultdict, deque, Counter
from itertools import combinations

def build_mcgee():
    n = 24
    edges = set()
    for i in range(n):
        u, v = i, (i+1) % n
        edges.add((min(u,v), max(u,v)))
    lcf = [-12, 7, -7]
    for i in range(n):
        offset = lcf[i % 3]
        j = (i + offset) % n
        u, v = min(i, j), max(i, j)
        edges.add((u, v))
    return list(edges)

def get_adj(edges, n):
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    return adj

def bfs_distances(adj, start, n):
    dist = [-1] * n
    dist[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for nb in adj[node]:
            if dist[nb] == -1:
                dist[nb] = dist[node] + 1
                queue.append(nb)
    return dist

mcgee_edges = build_mcgee()
adj24 = get_adj(mcgee_edges, 24)

all_dist = {}
for v in range(24):
    all_dist[v] = bfs_distances(adj24, v, 24)

dist_counts = Counter()
for a in range(24):
    for b in range(a+1, 24):
        dist_counts[all_dist[a][b]] += 1

print("Distance distribution in McGee graph:")
for d in sorted(dist_counts):
    print(f"  dist={d}: {dist_counts[d]} pairs")

